fix.code:
public final class OrderMetrics implements OrderListener {
    private final Counter placed;
    private final Counter failed;

    private OrderMetrics(MeterRegistry registry) {
        this.placed = registry.counter("orders.placed");
        this.failed = registry.counter("orders.failed");
    }

    public static OrderMetrics register(EventBus bus, MeterRegistry registry) {
        OrderMetrics metrics = new OrderMetrics(registry);
        bus.register(metrics);   // công bố sau khi constructor đã xong
        return metrics;
    }

    @Override
    public void onOrder(OrderEvent event) {
        if (event.ok()) placed.increment();
        else failed.increment();
    }
}
